-- CPF postgresql initial baseline for accDB


-- CPF_LOGICAL_DATABASE=accDB
-- CPF_USE_LOGICAL_DATABASE=accDB
CREATE TABLE acc_account (
    account_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    account_no VARCHAR(50) NOT NULL,
    account_name VARCHAR(150) NOT NULL,
    email VARCHAR(200),
    status_code VARCHAR(30) NOT NULL DEFAULT 'ACTIVE',
    row_version BIGINT NOT NULL DEFAULT 0,
    deleted_yn CHAR(1) NOT NULL DEFAULT 'N',
    created_by VARCHAR(100) NOT NULL,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_by VARCHAR(100) NOT NULL,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (account_id),
    CONSTRAINT uk_acc_account_no UNIQUE (account_no),
    CONSTRAINT ck_acc_account_deleted CHECK (deleted_yn IN ('Y', 'N'))
);
CREATE INDEX ix_acc_account_search ON acc_account (status_code, deleted_yn, account_id);
COMMENT ON TABLE acc_account IS 'ACC 중립 계정 reference';
COMMENT ON COLUMN acc_account.account_id IS '계정 식별자';
COMMENT ON COLUMN acc_account.account_no IS '업무 계정번호';
COMMENT ON COLUMN acc_account.account_name IS '계정명';
COMMENT ON COLUMN acc_account.email IS '마스킹 대상 이메일';
COMMENT ON COLUMN acc_account.status_code IS '계정 상태 코드';
COMMENT ON COLUMN acc_account.row_version IS '낙관적 잠금 버전';
COMMENT ON COLUMN acc_account.deleted_yn IS '논리 삭제 여부';
COMMENT ON COLUMN acc_account.created_by IS '등록자';
COMMENT ON COLUMN acc_account.created_at IS '등록일시';
COMMENT ON COLUMN acc_account.updated_by IS '수정자';
COMMENT ON COLUMN acc_account.updated_at IS '수정일시';
CREATE OR REPLACE FUNCTION fn_acc_account_touch() RETURNS trigger AS $$
BEGIN
    NEW.updated_at := CURRENT_TIMESTAMP;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;
CREATE TRIGGER trg_acc_account_touch BEFORE UPDATE ON acc_account
FOR EACH ROW EXECUTE FUNCTION fn_acc_account_touch();

CREATE TABLE acc_account_change_log (
    account_change_log_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    account_id BIGINT NOT NULL,
    action_code VARCHAR(30) NOT NULL,
    before_value TEXT,
    after_value TEXT,
    audit_reason VARCHAR(500) NOT NULL,
    created_by VARCHAR(100) NOT NULL,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_by VARCHAR(100) NOT NULL,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (account_change_log_id),
    CONSTRAINT fk_acc_account_change_target FOREIGN KEY (account_id) REFERENCES acc_account (account_id)
);
CREATE INDEX ix_acc_account_change_target ON acc_account_change_log (account_id, created_at);
COMMENT ON TABLE acc_account_change_log IS 'ACC 계정 변경 감사 이력';
COMMENT ON COLUMN acc_account_change_log.account_change_log_id IS '계정 변경 로그 순번';
COMMENT ON COLUMN acc_account_change_log.account_id IS '변경 계정 식별자';
COMMENT ON COLUMN acc_account_change_log.action_code IS 'CREATE, UPDATE 또는 DELETE 행위 코드';
COMMENT ON COLUMN acc_account_change_log.before_value IS '마스킹된 변경 전 값';
COMMENT ON COLUMN acc_account_change_log.after_value IS '마스킹된 변경 후 값';
COMMENT ON COLUMN acc_account_change_log.audit_reason IS '변경 감사 사유';
COMMENT ON COLUMN acc_account_change_log.created_by IS '등록자';
COMMENT ON COLUMN acc_account_change_log.created_at IS '등록일시';
COMMENT ON COLUMN acc_account_change_log.updated_by IS '수정자';
COMMENT ON COLUMN acc_account_change_log.updated_at IS '수정일시';
CREATE OR REPLACE FUNCTION fn_acc_account_change_log_touch() RETURNS trigger AS $$
BEGIN
    NEW.updated_at := CURRENT_TIMESTAMP;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;
CREATE TRIGGER trg_acc_account_change_log_touch BEFORE UPDATE ON acc_account_change_log
FOR EACH ROW EXECUTE FUNCTION fn_acc_account_change_log_touch();
